const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Canberra geometry
  const canberra = ee.Geometry.Point([149.13, -35.28]);
  const bufferGeom = canberra.buffer(50000); // 50 km buffer for region

  // 2. Define date range
  const startDate = '2020-01-14';
  const endDate = '2020-01-22';

  // 3. Load CHIRPS daily precipitation data
  let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterBounds(bufferGeom)
    .filterDate(startDate, endDate)
    .select('precipitation');

  const imgCount = chirps.size().getInfo();
  console.log(`CHIRPS Images Found: ${imgCount}`);

  if (imgCount === 0) {
    console.log('No precipitation data available for date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Sum all daily precipitation over the period
  const totalPrecip = chirps.sum();

  // 5. Calculate mean precipitation in mm over Canberra
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canberra,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const precipMM = stats['precipitation'];

  console.log(`Total Precipitation (mm): ${precipMM}`);

  // Validate result
  if (precipMM === null || precipMM === undefined || isNaN(precipMM)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMM / 25.4;
  console.log(`Total Precipitation (inches): ${precipInches.toFixed(2)}`);

  // 7. Compare to 8 inches threshold
  const threshold = 8;
  if (precipInches > threshold) {
    console.log(`Result: ${precipInches.toFixed(2)} inches > ${threshold} inches`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Result: ${precipInches.toFixed(2)} inches ≤ ${threshold} inches`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
